changeSet.sql:
delete ps from payslip_setting ps where not ps.template and not exists(select 1 from hr_monthly_data hr where hr.hr_value = ps.id and hr.hr_variable = 'TEMPLATE');
update payslip_setting_element pse LEFT JOIN payslip_setting ps on pse.payslip_setting_id = ps.id
set pse.company_id = ps.company_id;
